import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick check for strong univariate signals
    strong_uni = []
    for i, fid in enumerate(feats.ids):
        mean1 = np.mean(feats.x[feats.y==1, i])
        mean0 = np.mean(feats.x[feats.y==0, i])
        if abs(mean1 - mean0) > 0.3:
            strong_uni.append(fid)

    # Fast correlation check for top features
    if len(strong_uni) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check correlations among top features
    top_features = strong_uni[:10]  # Limit to speed up
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in top_features]].T)

    # Find strong correlations
    candidates = []
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            if abs(corr_matrix[i,j]) >= 0.6:
                candidates.append((fid1, fid2))

    if not candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use first pair
    fid1, fid2 = candidates[0]

    # Return design with product term
    return Design(
        drivers=(fid1, fid2),
        columns=(fid1, fid2),
        products=((fid1, fid2),),
        loadings={fid1: 1.0, fid2: 1.0}
    )

